.nodo-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing2);
  min-width: 64px;
  height: 48px;
  padding-inline: var(--spacing6);
  border: none;
  border-radius: var(--radius-small);
  font-family: inherit;
  font-size: 14px; line-height: 20px; font-weight: 600;
  cursor: pointer;
  isolation: isolate;
  transition: transform 100ms cubic-bezier(0.4, 0, 1, 1);
}
.nodo-btn::before { /* área táctil mínima 44dp sin alterar el layout */
  content: ""; position: absolute; inset: 50% auto auto 50%;
  width: 100%; height: 100%; min-width: 44px; min-height: 44px;
  transform: translate(-50%, -50%);
}
.nodo-btn__state-layer {
  position: absolute; inset: 0; z-index: 0;
  border-radius: inherit; opacity: 0;
  transition: opacity var(--transition-fast);
  pointer-events: none;
}
.nodo-btn > :not(.nodo-btn__state-layer) { position: relative; z-index: 1; }

/* Variantes */
.nodo-btn--filled   { background: var(--primary); color: var(--on-primary); }
.nodo-btn--filled   .nodo-btn__state-layer { background: var(--on-primary); }
.nodo-btn--tonal    { background: var(--primary-container); color: var(--on-primary-container); }
.nodo-btn--tonal    .nodo-btn__state-layer { background: var(--on-primary-container); }
.nodo-btn--outlined { background: transparent; color: var(--primary); border: 1px solid var(--outline); }
.nodo-btn--outlined .nodo-btn__state-layer { background: var(--primary); }
.nodo-btn--text     { background: transparent; color: var(--primary); padding-inline: var(--spacing3); }
.nodo-btn--text     .nodo-btn__state-layer { background: var(--primary); }

/* Tamaños */
.nodo-btn--xsmall { height: 32px; padding-inline: var(--spacing3); gap: var(--spacing1); border-radius: var(--radius-xSmall); font-size: 11px; line-height: 16px; }
.nodo-btn--small  { height: 40px; padding-inline: var(--spacing4); font-size: 12px; line-height: 16px; }
.nodo-btn--medium { height: 48px; }
.nodo-btn--large  { height: 56px; padding-inline: var(--spacing8); }
.nodo-btn--xlarge { height: 64px; padding-inline: var(--spacing10); border-radius: var(--radius-medium); font-size: 16px; line-height: 24px; }

/* Estados */
.nodo-btn:hover  .nodo-btn__state-layer { opacity: 0.08; }
.nodo-btn:focus-visible { outline: 2px solid var(--nodo-primary-light); outline-offset: 2px; }
.nodo-btn:focus-visible .nodo-btn__state-layer { opacity: 0.10; }
.nodo-btn:active .nodo-btn__state-layer { opacity: 0.10; }
.nodo-btn:active { transform: scale(0.98); }

.nodo-btn:disabled,
.nodo-btn[aria-disabled="true"] {
  cursor: not-allowed;
  background: color-mix(in srgb, var(--on-surface) 12%, transparent);
  border-color: transparent;
  color: color-mix(in srgb, var(--on-surface) 38%, transparent);
}
.nodo-btn:disabled .nodo-btn__state-layer { opacity: 0; }

.nodo-btn[aria-busy="true"] { pointer-events: none; }
.nodo-btn[aria-busy="true"] .nodo-btn__icon { opacity: 0; }

.nodo-btn--error { background: var(--error); color: var(--on-error); }
.nodo-btn--fill  { width: 100%; }

@media (prefers-reduced-motion: reduce) {
  .nodo-btn:active { transform: none; }
}
